package com.bank.diversity;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class PartitionDemo {
    private static final Logger log = Logger.getLogger("Diversity");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", Gender.MALE),
            new Employee("Neha", "IT", Gender.FEMALE),
            new Employee("Amit", "Sales", Gender.MALE));
        DiversityService service = new DiversityService();

        Map<String, Map<Boolean, List<String>>> split = service.byDepartmentAndGender(staff);
        split.forEach((dept, m) -> log.info(() -> dept
            + " → male=" + m.get(true) + " female=" + m.get(false)));
    }
}

// ─── Would be in model/Gender.java ───
enum Gender { MALE, FEMALE }

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final Gender gender;
    Employee(String name, String department, Gender gender) {
        this.name = name; this.department = department; this.gender = gender;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    Gender getGender() { return gender; }
}

// ─── Would be in service/DiversityService.java ───
class DiversityService {
    Map<String, Map<Boolean, List<String>>> byDepartmentAndGender(List<Employee> staff) {
        return staff.stream()
            .collect(groupingBy(
                Employee::getDepartment,                          // outer: department
                partitioningBy(e -> e.getGender() == Gender.MALE, // inner: true=male
                    mapping(Employee::getName, toList()))));        // store names
    }
}
